window.BOOK={"key":"laqit","app":"mutoon-laqit","lsk":"mutoon_laqit_v1","prefix":"la_","title":"عينية لقيط","sub":"الشعر العربي · لقيط بن يعمر الإيادي (ت نحو ٢٥٠ ق.هـ) · ٥٦ بيتًا","poems":[{"id":"laqit","title":"عينية لقيط","nazim":"لقيط بن يعمر الإيادي","death":"ت نحو ٢٥٠ ق.هـ","meter":"البسيط","source":"المكتبة الشاملة: مختارات شعراء العرب لابن الشجري","srcUrl":"https://shamela.ws/book/740/2","note":"القصيدة برواية مختارات ابن الشجري وترتيبها (٥٦ بيتًا). المختارات مشكولة شكلًا جزئيًّا (نحو ١٨٪ من الحروف)، فأُكمل الشكل ونُقل ما أمكن من الذخائر والعبقريات وأمالي المرزوقي ونص الموسوعة الشعرية المشكولة، وقوبل كلمةً كلمةً بسكربت بها، وفُحص وزن كل شطر على البسيط. التفاصيل وعدد المواضع المكمَّلة في تقرير المصادر.","verses":[["يَا دَارَ عَمْرَةَ مِنْ مُحْتَلِّهَا الْجَرَعَا","هَاجَتْ لِيَ الْهَمَّ وَالْأَحْزَانَ وَالْوَجَعَا"],["تَامَتْ فُؤَادِي بِذَاتِ الْجِزْعِ خَرْعَبَةٌ","مَرَّتْ تُرِيدُ بِذَاتِ الْعَذْبَةِ الْبِيَعَا"],["بِمُقْلَتَيْ خَاذِلٍ أَدْمَاءَ طَاعَ لَهَا","نَبْتُ الرِّيَاضِ تُزَجِّي وَسْطَهُ ذَرَعَا"],["وَوَاضِحٍ أَشْنَبِ الْأَنْيَابِ ذِي أُشُرٍ","كَالْأُقْحُوَانِ إِذَا مَا نُورُهُ لَمَعَا"],["جَرَّتْ لِمَا بَيْنَنَا حَبْلَ الشُّمُوسِ فَلَا","يَأْسًا مُبِينًا أَرَى مِنْهَا وَلَا طَمَعَا"],["فَمَا أَزَالُ عَلَى شَحْطٍ يُؤَرِّقُنِي","طَيْفٌ تَعَمَّدَ رَحْلِي حَيْثُمَا وُضِعَا"],["إِنِّي بِعَيْنِيَ إِذْ أَمَّتْ حُمُولُهُمُ","بَطْنَ السَّلَوْطَحِ لَا يَنْظُرْنَ مَنْ تَبِعَا"],["طَوْرًا أَرَاهُمْ وَطَوْرًا لَا أُبَيِّنُهُمْ","إِذَا تَوَاضَعَ خِدْرٌ سَاعَةً لَمَعَا"],["بَلْ أَيُّهَا الرَّاكِبُ الْمُزْجِي مَطِيَّتَهُ","إِلَى الْجَزِيرَةِ مُرْتَادًا وَمُنْتَجِعَا"],["أَبْلِغْ إِيَادًا وَخَلِّلْ فِي سَرَاتِهِمُ","أَنِّي أَرَى الرَّأْيَ إِنْ لَمْ أُعْصَ قَدْ نَصَعَا"],["يَا لَهْفَ نَفْسِيَ إِنْ كَانَتْ أُمُورُكُمُ","شَتَّى وَأُحْكِمَ أَمْرُ النَّاسِ فَاجْتَمَعَا"],["إِنِّي أَرَاكُمْ وَأَرْضًا تُعْجَبُونَ بِهَا","مِثْلَ السَّفِينَةِ تَغْشَى الْوَعْثَ وَالطَّبَعَا"],["أَلَا تَخَافُونَ قَوْمًا لَا أَبَا لَكُمُ","أَمْسَوْا إِلَيْكُمْ كَأَمْثَالِ الدَّبَى سُرُعَا"],["أَبْنَاءُ قَوْمٍ تَآوَوْكُمْ عَلَى حَنَقٍ","لَا يَشْعُرُونَ أَضَرَّ اللَّهُ أَمْ نَفَعَا"],["أَحْرَارُ فَارِسَ أَبْنَاءُ الْمُلُوكِ لَهُمْ","مِنَ الْجُمُوعِ جُمُوعٌ تَزْدَهِي الْقِلَعَا"],["فَهُمْ سِرَاعٌ إِلَيْكُمْ بَيْنَ مُلْتَقِطٍ","شَوْكًا وَآخَرَ يَجْنِي الصَّابَ وَالسَّلَعَا"],["لَوْ أَنَّ جَمْعَهُمُ رَامُوا بِهَدَّتِهِ","شُمَّ الشَّمَارِيخِ مِنْ ثَهْلَانَ لَانْصَدَعَا"],["فِي كُلِّ يَوْمٍ يَسُنُّونَ الْحِرَابَ لَكُمْ","لَا يَهْجَعُونَ إِذَا مَا غَافِلٌ هَجَعَا"],["خُزْرٌ عُيُونُهُمُ كَأَنَّ لَحْظَهُمُ","حَرِيقُ غَابٍ تَرَى مِنْهُ السَّنَا قِطَعَا"],["لَا الْحَرْثُ يَشْغَلُهُمْ بَلْ لَا يَرَوْنَ لَهُمْ","مِنْ دُونِ بَيْضَتِكُمْ رِيًّا وَلَا شِبَعَا"],["وَأَنْتُمُ تَحْرُثُونَ الْأَرْضَ عَنْ سَفَهٍ","فِي كُلِّ مُعْتَمَلٍ تَبْغُونَ مُزْدَرَعَا"],["وَتُلْقِحُونَ حِيَالَ الشَّوْلِ آوِنَةً","وَتَنْتِجُونَ بِدَارِ الْقُلْعَةِ الرُّبَعَا"],["وَتَلْبَسُونَ ثِيَابَ الْأَمْنِ ضَاحِيَةً","لَا تَفْزَعُونَ وَهَذَا اللَّيْثُ قَدْ جَمَعَا"],["وَقَدْ أَظَلَّكُمُ مِنْ شَطْرِ ثَغْرِكُمُ","هَوْلٌ لَهُ ظُلَمٌ تَغْشَاكُمُ قِطَعَا"],["مَالِي أَرَاكُمْ نِيَامًا فِي بُلَهْنِيَةٍ","وَقَدْ تَرَوْنَ شِهَابَ الْحَرْبِ قَدْ سَطَعَا"],["فَاشْفُوا غَلِيلِي بِرَأْيٍ مِنْكُمُ حَصِدٍ","يُصْبِحْ فُؤَادِي لَهُ رَيَّانَ قَدْ نَقَعَا"],["وَلَا تَكُونُوا كَمَنْ قَدْ بَاتَ مُكْتَنِعًا","إِذَا يُقَالُ لَهُ افْرُجْ غُمَّةً كَنَعَا"],["يَسْعَى وَيَحْسَبُ أَنَّ الْمَالَ مُخْلِدُهُ","إِذَا اسْتَفَادَ طَرِيفًا زَادَهُ طَمَعَا"],["فَاقْنُوا جِيَادَكُمُ وَاحْمُوا ذِمَارَكُمُ","وَاسْتَشْعِرُوا الصَّبْرَ لَا تَسْتَشْعِرُوا الْجَزَعَا"],["وَلَا يَدَعْ بَعْضُكُمْ بَعْضًا لِنَائِبَةٍ","كَمَا تَرَكْتُمْ بِأَعْلَى بِيشَةَ النَّخَعَا"],["صُونُوا جِيَادَكُمُ وَاجْلُوا سُيُوفَكُمُ","وَجَدِّدُوا لِلْقِسِيِّ النَّبْلَ وَالشِّرَعَا"],["أَذْكُوا الْعُيُونَ وَرَاءَ السَّرْحِ وَاحْتَرِسُوا","حَتَّى تُرَى الْخَيْلُ مِنْ تَعْدَائِهَا رُجُعَا"],["وَاشْرُوا تِلَادَكُمُ فِي حِرْزِ أَنْفُسِكُمْ","وَحِرْزِ أَهْلِيكُمُ لَا تَهْلِكُوا هَلَعَا"],["فَإِنْ غُلِبْتُمْ عَلَى ضِنٍّ بِدَارِكُمُ","فَقَدْ لَقِيتُمْ بِأَمْرِ الْحَازِمِ الْفَزَعَا"],["لَا تُلْهِكُمْ إِبِلٌ لَيْسَتْ لَكُمْ إِبِلٌ","إِنَّ الْعَدُوَّ بِعَظْمٍ مِنْكُمُ قَرَعَا"],["لَا تُثْمِرُوا الْمَالَ لِلْأَعْدَاءِ إِنَّهُمُ","إِنْ يَظْهَرُوا يَحْتَوُوكُمْ وَالتِّلَادَ مَعَا"],["هَيْهَاتَ لَا مَالَ مِنْ زَرْعٍ وَلَا إِبِلٍ","يُرْجَى لِغَابِرِكُمْ إِنْ أَنْفُكُمْ جُدِعَا"],["وَاللَّهِ مَا انْفَكَّتِ الْأَمْوَالُ مُذْ أَبَدٍ","لِأَهْلِهَا إِنْ أُصِيبُوا مَرَّةً تَبَعَا"],["يَا قَوْمِ إِنَّ لَكُمْ مِنْ إِرْثِ أَوَّلِكُمْ","مَجْدًا قَدَ اشْفَقْتُ أَنْ يَفْنَى وَيَنْقَطِعَا"],["مَاذَا يَرُدُّ عَلَيْكُمْ عِزُّ أَوَّلِكُمْ","إِنْ ضَاعَ آخِرُهُ أَوْ ذَلَّ وَاتَّضَعَا"],["يَا قَوْمِ لَا تَأْمَنُوا إِنْ كُنْتُمُ غُيُرًا","عَلَى نِسَائِكُمُ كِسْرَى وَمَا جَمَعَا"],["يَا قَوْمِ بَيْضَتُكُمْ لَا تُفْجَعُنَّ بِهَا","إِنِّي أَخَافُ عَلَيْهَا الْأَزْلَمَ الْجَذَعَا"],["هُوَ الْجَلَاءُ الَّذِي يَجْتَثُّ أَصْلَكُمُ","فَمَنْ رَأَى مِثْلَ ذَا رَأْيًا وَمَنْ سَمِعَا"],["قُومُوا قِيَامًا عَلَى أَمْشَاطِ أَرْجُلِكُمْ","ثُمَّ افْزَعُوا قَدْ يَنَالُ الْأَمْنَ مَنْ فَزِعَا"],["وَقَلِّدُوا أَمْرَكُمْ لِلَّهِ دَرُّكُمُ","رَحْبَ الذِّرَاعِ بِأَمْرِ الْحَرْبِ مُضْطَلِعَا"],["لَا مُتْرَفًا إِنْ رَخَاءُ الْعَيْشِ سَاعَدَهُ","وَلَا إِذَا عَضَّ مَكْرُوهٌ بِهِ خَشَعَا"],["لَا يَطْعَمُ النَّوْمَ إِلَّا رَيْثَ يَبْعَثُهُ","هَمٌّ يَكَادُ سَنَاهُ يَقْصِمُ الضِّلَعَا"],["مُسَهَّدَ النَّوْمِ تَعْنِيهِ أُمُورُكُمُ","يَرُومُ مِنْهَا إِلَى الْأَعْدَاءِ مُطَّلَعَا"],["مَا انْفَكَّ يَحْلُبُ هَذَا الدَّهْرَ أَشْطُرَهُ","يَكُونُ مُتَّبِعًا طَوْرًا وَمُتَّبَعَا"],["حَتَّى اسْتَمَرَّتْ عَلَى شَزْرٍ مَرِيرَتُهُ","مُسْتَحْكِمَ الرَّأْيِ لَا قَحْمًا وَلَا ضَرَعَا"],["وَلَيْسَ يَشْغَلُهُ مَالٌ يُثَمِّرُهُ","عَنْكُمْ وَلَا وَلَدٌ يَبْغِي لَهُ الرِّفَعَا"],["كَمَالِكِ بْنِ قَنَانٍ أَوْ كَصَاحِبِهِ","عَمْرِو الْقَنَا يَوْمَ لَاقَى الْحَارِثَيْنِ مَعَا"],["إِذْ عَابَهُ عَائِبٌ يَوْمًا فَقَالَ لَهُ","دَمِّثْ لِجَنْبِكَ قَبْلَ اللَّيْلِ مُضْطَجَعَا"],["فَشَاوَرُوهُ فَأَلْفَوْهُ أَخَا عَلَلٍ","فِي الْحَرْبِ لَا عَاجِزًا نِكْسًا وَلَا وَرَعَا"],["لَقَدْ بَذَلْتُ لَكُمْ نُصْحِي بِلَا دَخَلٍ","فَاسْتَيْقِظُوا إِنَّ خَيْرَ الْعِلْمِ مَا نَفَعَا"],["هَذَا كِتَابِي إِلَيْكُمْ وَالنَّذِيرُ لَكُمْ","لِمَنْ رَأَى رَأْيَهُ مِنْكُمْ وَمَنْ سَمِعَا"]],"secs":{"1":"عينية لقيط بن يعمر"}}],"sharh":false};
